function d_proof_check(P,R){var steps=P.steps||[];var known={};var ok=true;steps.forEach(function(s){var good=false;if(s.rule==='assumption')good=true;else if(s.rule==='modus-ponens'){good=!!(known[s.from]&&known[s.impl]&&s.impl.indexOf(s.from)===0);}else if(s.rule==='and-intro'){good=!!(known[s.left]&&known[s.right]);}if(good)known[s.conclusion]=true;else ok=false;});return{steps_checked:steps.length,valid:ok,conclusion:steps.length?steps[steps.length-1].conclusion:null};}

