function d_fault_inject(P,R){var trials=P.trials||30,recovered=0,times=[];for(var i=0;i<trials;i++){var t=5+R()*20;if(R()<(P.recovery||0.9)){recovered++;times.push(t);}}times.sort(function(a,b){return a-b;});return{trials:trials,recovered:recovered,recovery_rate:+(recovered/trials).toFixed(3),p50_recovery_s:+times[Math.floor(times.length/2)].toFixed(1)};}

